fn hv(i: i32) -> i32 {
    let s: i32 = i * 1103515245 + 12345;
    ((s >> 16) & 32767) % 80 + 10
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0a0a0a);
    let base: i32 = h - 60;
    let mut i: i32 = 0;
    while i < 40 {
        let x: i32 = 8 + i * (w - 16) / 39;
        let y: i32 = base - hv(i) * 3;
        host::display::fill_rect(x - 1, y - 1, 3, 3, 0x707070);
        i = i + 1;
    }
    i = 4;
    while i < 40 {
        let a0: i32 = (hv(i - 4) + hv(i - 3) + hv(i - 2) + hv(i - 1)) / 4;
        let a1: i32 = (hv(i - 3) + hv(i - 2) + hv(i - 1) + hv(i)) / 4;
        let x0: i32 = 8 + (i - 1) * (w - 16) / 39;
        let x1: i32 = 8 + i * (w - 16) / 39;
        host::display::draw_line(x0, base - a0 * 3, x1, base - a1 * 3, 0x00d0ff);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "RAW", 0x707070, 2);
    host::display::draw_string(70, 8, "SMOOTH", 0x00d0ff, 2);
    host::display::present();
}
